#include <iostream>
#include <cmath>

using namespace std;
int main(){
    int a, b, c;
    cin >> a >> b >> c;
    if (c > 2) c = 2 + (c % 2);

    double x = pow(a, c);
    double y = pow(b, c);
    cout << ( x>y ? ">" : x<y ? "<" : "=") << endl;
}
